    def pick_permutation(self, current, m, n):
        if len(current)==n:
            yield current
        else:
            if not current:
                start = 0
            else:
                start = current[-1]
            for i in range(start, m+1):
                new_current = current[:]
                new_current.append(i)
                for perm in self.pick_permutation(new_current,m,n):
                    yield perm

